        {id:"s6b-minimize",label:"\u53ea\u627f\u8ba4\u201c\u8868\u8fbe\u4e0d\u591f\u4e25\u8c28\u201d\uff0c\u62d2\u7edd\u8bfb\u51fa\u539f\u9519\u53e5\uff0c\u4e94\u95ee\u4ee5\u6b63\u5728\u8c03\u67e5\u4e3a\u4e3b",desc:"\u628a\u5b9e\u8d28\u4e8b\u5b9e\u9519\u8bef\u964d\u683c\u4e3a\u63aa\u8f9e\u95ee\u9898\u3002",effect:"wound",work:"\u5404\u90e8\u95e8\u8868\u793a\u524d\u671f\u4e2a\u522b\u8868\u8ff0\u4e0d\u591f\u4e25\u8c28\uff0c\u5411\u516c\u4f17\u81f4\u6b49\uff0c\u4f46\u4e0d\u590d\u8ff0\u539f\u9519\u53e5\u548c\u5177\u4f53\u4e8b\u5b9e\uff0c\u4e94\u95ee\u8be6\u7ec6\u8d23\u4efb\u5f85\u6700\u7ec8\u8c03\u67e5\u62a5\u544a\u786e\u5b9a\u3002",feedback:"\u201c\u4e0d\u662f\u4e8b\u5b9e\u9519\u4e86\uff0c\u53ea\u662f\u8bf4\u5f97\u4e0d\u597d\u201d\u6210\u4e3a\u65b0\u6279\u8bc4\u70b9\uff0c\u6574\u6539\u627f\u8bfa\u96be\u4ee5\u62b5\u6d88\u65e7\u4f24\u3002",material:"\u8868\u8fbe\u4e0d\u4e25\u8c28\u7248\u907f\u91cd\u7b54\u95ee\u5b9e\u5f55",comments:[["\u90fd\u5e02\u73b0\u573a","\u8bfe\u8868\u8bc1\u660e\u539f\u8bdd\u4e0e\u4e8b\u5b9e\u76f8\u53cd\uff0c\u8fd9\u8fd8\u53ea\u662f\u8868\u8fbe\u4e0d\u4e25\u8c28\u5417\uff1f"]]},
        {id:"s6b-confront",label:"\u53d1\u8a00\u4eba\u9010\u6761\u53cd\u9a73\u8bb0\u8005\uff0c\u5426\u8ba4\u65e7\u58f0\u660e\u5b58\u5728\u9519\u8bef\u5e76\u4e2d\u65ad\u4e0d\u5229\u8ffd\u95ee",desc:"\u5728\u6700\u540e\u516c\u5f00\u573a\u91cd\u65b0\u5426\u5b9a\u5df2\u6838\u5b9e\u4e8b\u5b9e\u3002",effect:"crisis",work:"\u5404\u90e8\u95e8\u7ef4\u6301\u539f\u58f0\u660e\u57fa\u672c\u4e8b\u5b9e\u65e0\u8bef\uff0c\u53d1\u8a00\u4eba\u8981\u6c42\u8bb0\u8005\u505c\u6b62\u91cd\u590d\u7092\u4f5c\u65e7\u6750\u6599\uff0c\u5bf9\u901a\u9053\u3001\u7269\u4e1a\u548c\u6570\u5b57\u4e0d\u5229\u8ffd\u95ee\u76f4\u63a5\u8f6c\u4e0b\u4e00\u9898\u3002",feedback:"\u76f4\u64ad\u4e2d\u65ad\u8ffd\u95ee\u4e0e\u65e7\u8bc1\u636e\u5e76\u5217\u4f20\u64ad\uff0c\u53d1\u5e03\u4f1a\u4ece\u8865\u6551\u573a\u53d8\u6210\u4e8c\u6b21\u5bf9\u8d28\u573a\u3002",material:"\u53d1\u5e03\u4f1a\u53cd\u9a73\u8bb0\u8005\u4e0e\u4e2d\u65ad\u8ffd\u95ee\u5207\u7247",comments:[["\u7ea2\u661f\u8bb0\u8005","\u8bc1\u636e\u5df2\u7ecf\u516c\u5f00\uff0c\u4e3a\u4ec0\u4e48\u73b0\u573a\u4ecd\u8bf4\u539f\u58f0\u660e\u6ca1\u6709\u9519\uff1f"]]}
